import React, { useEffect, useState, useRef } from "react";
import { GoogleMap, Marker, DirectionsRenderer, useJsApiLoader } from "@react-google-maps/api";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";

const containerStyle = {
  width: "100%",
  height: "600px",
};

const API_BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:5000";

export default function DeliveryTrackingPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();

  const [initialDriverLocation, setInitialDriverLocation] = useState<{ lat: number; lng: number } | null>(null);
  const [driverLocation, setDriverLocation] = useState<{ lat: number; lng: number } | null>(null);
  const [deliveryLocation, setDeliveryLocation] = useState<{ lat: number; lng: number } | null>(null);
  const [directions, setDirections] = useState<google.maps.DirectionsResult | null>(null);
  const [routePath, setRoutePath] = useState<google.maps.LatLngLiteral[]>([]);
  const [currentStep, setCurrentStep] = useState(0);

  const mapRef = useRef<google.maps.Map>();

  const { isLoaded } = useJsApiLoader({
    googleMapsApiKey: process.env.REACT_APP_GOOGLE_MAPS_API_KEY!,
  });

  const geocodeAddress = async (address: string): Promise<{ lat: number; lng: number } | null> => {
    try {
      const response = await axios.get(
        `https://maps.googleapis.com/maps/api/geocode/json?address=${encodeURIComponent(address)}&key=${process.env.REACT_APP_GOOGLE_MAPS_API_KEY}`
      );
      if (response.data.status === "OK") {
        return response.data.results[0].geometry.location;
      } else {
        console.error("Geocoding failed:", response.data.status);
        return null;
      }
    } catch (error) {
      console.error("Geocoding error:", error);
      return null;
    }
  };

  useEffect(() => {
    if (!id) return;

    const fetchData = async () => {
      try {
        const deliveryRes = await axios.get(`${API_BASE_URL}/api/delivery/${id}`);
        const delivery = deliveryRes.data;
        if (delivery.location) {
          setDeliveryLocation(delivery.location);
        }

        const driverRes = await axios.get(`${API_BASE_URL}/api/drivers/${delivery.driverId}`);
        const driver = driverRes.data;

        if (driver.address) {
          const driverCoords = await geocodeAddress(driver.address);
          if (driverCoords) {
            setInitialDriverLocation(driverCoords); // Keep initial driver address
          }
        }
      } catch (error) {
        console.error("Error fetching delivery or driver info:", error);
      }
    };

    fetchData();
  }, [id]);

  useEffect(() => {
    if (!initialDriverLocation || !deliveryLocation) return;

    const directionsService = new google.maps.DirectionsService();
    directionsService.route(
      {
        origin: initialDriverLocation,
        destination: deliveryLocation,
        travelMode: google.maps.TravelMode.DRIVING,
      },
      (result, status) => {
        if (status === "OK" && result) {
          setDirections(result);

          const path = result.routes[0].overview_path.map((latlng) => ({
            lat: latlng.lat(),
            lng: latlng.lng(),
          }));

          setRoutePath(path);

          if (path.length > 0) {
            setDriverLocation(path[0]); // Start moving after route is ready
          }
        } else {
          console.error("Directions request failed:", status);
        }
      }
    );
  }, [initialDriverLocation, deliveryLocation]);

  // 🛠 Move Driver Along Road
  useEffect(() => {
    if (routePath.length === 0) return;

    const interval = setInterval(() => {
      setCurrentStep((prevStep) => {
        if (prevStep >= routePath.length - 1) {
          clearInterval(interval);
          return prevStep;
        }
        setDriverLocation(routePath[prevStep + 1]);
        return prevStep + 1;
      });
    }, 1000); // Move every 1 second

    return () => clearInterval(interval);
  }, [routePath]);

  if (!isLoaded) return <div>Loading Map...</div>;

  return (
    <div style={{ padding: "20px" }}>
      <h2>🚚 Tracking Delivery (Driver Moving Along Road)</h2>

      <button onClick={() => navigate("/")} style={backButtonStyle}>
        ← Back to Dashboard
      </button>

      {driverLocation && deliveryLocation && (
        <GoogleMap
          mapContainerStyle={containerStyle}
          onLoad={(map) => {
            mapRef.current = map;

            const bounds = new window.google.maps.LatLngBounds();
            bounds.extend(driverLocation);
            bounds.extend(deliveryLocation);
            map.fitBounds(bounds);
          }}
        >
          {/* Driver Marker */}
          <Marker
            position={driverLocation}
            label="Driver"
            icon={{
              url: "http://maps.google.com/mapfiles/ms/icons/blue-dot.png",
            }}
          />

          {/* Delivery Marker */}
          <Marker
            position={deliveryLocation}
            label="Delivery"
            icon={{
              url: "http://maps.google.com/mapfiles/ms/icons/red-dot.png",
            }}
          />

          {/* Draw the Delivery Route */}
          {directions && (
            <DirectionsRenderer
              directions={directions}
              options={{
                suppressMarkers: true,
                polylineOptions: {
                  strokeColor: "#1E90FF",   // Blue Route
                  strokeOpacity: 0.8,
                  strokeWeight: 6,
                },
              }}
            />
          )}
        </GoogleMap>
      )}
    </div>
  );
}

const backButtonStyle = {
  marginBottom: "20px",
  padding: "10px 20px",
  backgroundColor: "#6c757d",
  color: "#fff",
  border: "none",
  borderRadius: "4px",
  cursor: "pointer",
};
